/**
 * Banner DXP Component Service -- Server-Side Renderer
 *
 * Static HTML only -- no client-side interactivity (matches the Footer /
 * Header / GlobalAlert edge patterns). Buttons use this project's real
 * shared `.button` / `.button-secondary` / `.button-tertiary` primitive
 * (src/css-components/buttons.css), not Bootstrap `.btn-*` classes -- see
 * banner.spec.md assumption 3.
 */

const VALID_VARIANTS = new Set(["primary", "secondary"]);
const VALID_CTA_VARIANTS = new Set(["primary", "secondary", "tertiary"]);
const VALID_LINKS_HEADINGS = new Set(["Popular", "Featured", "Related"]);

/**
 * Real NTG logo mono mark -- the actual legacy watermark asset (previously
 * an unresolvable `%globals_asset_contents_raw:1240478%` include; see
 * banner.spec.md assumption 7, now resolved). Embedded exactly as supplied,
 * with a class added to the <svg> root for CSS sizing/positioning only --
 * the artwork itself (paths, opacity, fill) is unmodified.
 */
const NTG_LOGO_SVG = `<svg class="banner__decorative-logo" xmlns="http://www.w3.org/2000/svg" width="500" height="500" viewBox="0 0 284.757 287.367">
      <g id="logo-ntg-mono" opacity="0.5">
        <path id="Path_3" data-name="Path 3" d="M120.044,1.847C107.731,3.694,95.727,23.393,100.96,38.168c7.08,20.315,22.162,54.174,43.093,54.789,21.238-.616,36.013-34.166,43.093-54.789,5.233-14.775-7.079-33.551-19.084-36.321-11.389-2.462-32.012-2.462-48.017,0M18.776,74.181c-6.156,11.081,1.231,32.935,15.7,37.86,20.007,7.079,55.4,16.006,68.948-.308C116.35,94.5,99.729,61.561,88.648,43.093c-8-13.236-30.165-15.39-39.707-7.387C39.4,43.4,26.779,59.714,18.776,74.181m-8,126.2c4.617,11.7,25.856,19.392,38.783,11.081,17.853-11.7,46.786-34.166,42.477-55.4C86.8,135.126,51.4,127.739,30.165,124.969,15.082,123.122,0,139.435,0,152.055c0,12.312,4.617,32.935,10.773,48.325m91.418,84.954c12,3.694,31.088-8.618,32.627-24.317,2.155-21.546,3.078-58.791-15.7-68.64-19.392-8.926-47.094,14.775-62.176,30.165-10.773,11.081-8,33.551,1.847,41.246,9.234,7.7,28.01,16.621,43.4,21.546m121.89-20.007c10.158-7.08,12.62-30.165,1.847-41.246-15.082-15.39-43.093-39.091-62.176-30.165-18.776,9.85-17.853,46.786-15.7,68.64,1.539,15.7,20.623,27.395,32.627,24.317,11.7-3.078,30.165-12.312,43.4-21.546m60.637-110.194c.923-12.62-15.082-28.934-30.473-27.087-21.239,2.462-56.636,10.158-61.869,31.088-4.309,21.238,24.624,43.708,42.477,55.4,12.928,8.311,33.551.616,38.783-10.773,5.54-11.7,10.158-32.012,11.081-48.633M238.548,37.86c-9.234-8.619-31.7-5.848-39.707,7.387-11.081,18.468-27.7,51.4-14.775,68.64,13.543,16.621,48.633,7.387,68.948.308,14.467-4.925,21.238-26.471,16.006-37.86-5.848-10.773-18.468-27.395-30.473-38.476" transform="translate(0 0)" fill="#ababab"></path>
        <path id="Path_4" data-name="Path 4" d="M128.792,27.062c-1.539,9.234-13.543,32.935-4,45.247,10.158,13.236,34.782,5.54,44.324,6.464l-1.231.308c-8,4.617-33.551,9.85-36.937,24.932-3.694,16.314,17.545,31.4,22.778,39.4l-1.231-.616c-8.311-3.694-28.626-20.931-42.169-14.159C95.55,136.025,97.4,161.881,94.318,171.115v-1.231c-2.462-8.926-1.847-35.705-15.39-42.477-15.082-7.387-33.858,10.158-42.785,13.543l.923-.923c5.233-7.7,26.163-23.7,22.778-38.783C56.151,84.93,30.911,80.928,22.6,76l1.231.308c9.234-.308,34.474,6.156,44.016-6.156C78,56.919,65.385,34.142,64.154,24.6l.616,1.231c6.156,7.079,16.929,31.4,32.012,31.4,16.314,0,25.856-24.317,32.319-31.4l-.308,1.231Z" transform="translate(46.964 51.12)" fill="#ababab"></path>
      </g>
    </svg>`;

/** HTML-escape for text content and attribute values. */
function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

/** `.button` primitive class list for a given CTA variant ("primary" is the bare, unmodified class). */
function buttonClass(variant) {
  return variant === "primary" ? "button" : `button button-${variant}`;
}

/**
 * Renders a simple <nav><ol class="breadcrumb"> trail. No truncation menu
 * (edge is static; menus require client-side state).
 */
function renderBreadcrumbs(items) {
  if (!items || items.length === 0) return "";

  // Normalise: if no item is flagged isCurrent, treat the last item as current.
  const currentIndex = items.findIndex((item) => item.isCurrent);
  const resolvedCurrentIndex =
    currentIndex >= 0 ? currentIndex : items.length - 1;

  const listItems = items
    .map((item, index) => {
      const isCurrent = index === resolvedCurrentIndex;
      const liClass = `breadcrumb-item${isCurrent ? " active" : ""}`;
      const ariaCurrent = isCurrent ? ` aria-current="page"` : "";
      const inner = isCurrent
        ? `<span class="content-breadcrumbs__current" data-sq-field="label">${esc(item.label)}</span>`
        : `<a class="content-breadcrumbs__link" href="${esc(item.href ?? "#")}" data-sq-field="label">${esc(item.label)}</a>`;
      return `        <li class="${liClass}"${ariaCurrent}>${inner}</li>`;
    })
    .join("\n");

  return `
    <div class="banner__breadcrumbs">
      <nav aria-label="Breadcrumb" class="content-breadcrumbs">
        <ol class="breadcrumb content-breadcrumbs__list">
${listItems}
        </ol>
      </nav>
    </div>`;
}

/**
 * Description paragraph, with an optional inline underlined link appended
 * inside the same block (mirrors the legacy `intro-textLink`/
 * `intro-textLinkWording` fields) -- distinct from the CTA button.
 */
function renderDescription(description, linkText, linkHref) {
  if (!description) return "";
  const link =
    linkText && linkHref
      ? ` <a href="${esc(linkHref)}" class="banner__description-link" data-sq-field="descriptionLinkText">${esc(linkText)}</a>`
      : "";
  return `<p class="banner__description" data-sq-field="description">${esc(description)}${link}</p>`;
}

/** CTA block: an <a> when ctaHref is supplied, or a <button> fallback. */
function renderCta(ctaText, ctaHref, buttonVariant) {
  if (!ctaText) return "";
  const cls = buttonClass(buttonVariant);
  const inner = ctaHref
    ? `<a href="${esc(ctaHref)}" class="${cls}" data-sq-field="ctaText">${esc(ctaText)}</a>`
    : `<button type="button" class="${cls}" data-sq-field="ctaText">${esc(ctaText)}</button>`;
  return `
          <div class="banner__cta">
            ${inner}
          </div>`;
}

/**
 * Decorative background -- the real NTG logo mono mark, positioned/sized
 * via CSS. Same asset on both variants; purely ornamental -- aria-hidden.
 */
function renderDecorative() {
  return `
      <div class="banner__decorative" aria-hidden="true">
        ${NTG_LOGO_SVG}
      </div>`;
}

/**
 * Links panel. Secondary variant renders a vertical plain-text link list;
 * primary variant renders flat pill-style links (`.banner__pill-link`, its
 * own CSS -- not the shared `.button` primitive, which carries a border
 * this treatment doesn't use) -- see banner.spec.md assumption 4 for why
 * this differs from the legacy template's single unstyled list.
 */
function renderLinks(linksHeading, links, isSecondary) {
  if (!linksHeading || !links || links.length === 0) return "";
  if (!VALID_LINKS_HEADINGS.has(linksHeading)) return "";

  let linkItems;
  if (isSecondary) {
    linkItems = links
      .map(
        (link) =>
          `            <a href="${esc(link.href)}" class="banner__link" data-sq-field="label">${esc(link.label)}</a>`,
      )
      .join("\n");
    linkItems = `
          <div class="banner__links-vertical">
${linkItems}
          </div>`;
  } else {
    linkItems = links
      .map(
        (link) =>
          `            <a href="${esc(link.href)}" class="banner__pill-link" data-sq-field="label">${esc(link.label)}</a>`,
      )
      .join("\n");
    linkItems = `
          <div class="banner__links-list">
${linkItems}
          </div>`;
  }

  return `

        <div class="banner__links">
          <h2 class="banner__links-heading">${esc(linksHeading)}</h2>${linkItems}
        </div>`;
}

/**
 * CTA-only right-hand column, used when there's no links panel to occupy
 * that slot. Mirrors the legacy template's `col-md-5` column, which held
 * either the popular-links block or the button block -- never both, and
 * never the button inline under the description.
 */
function renderCtaAside(ctaHtml) {
  return `

        <div class="banner__links">${ctaHtml}
        </div>`;
}

export default {
  async main(input) {
    const {
      variant = "primary",
      title = "",
      description = "",
      descriptionLinkText = "",
      descriptionLinkHref = "",
      ctaText = "",
      ctaHref = "",
      ctaVariant,
      linksHeading = "",
      links = [],
      breadcrumbs = [],
      label = "",
      href = "",
      showDecorative,
    } = input || {};

    const safeVariant = VALID_VARIANTS.has(variant) ? variant : "primary";
    const isSecondary = safeVariant === "secondary";

    // Default ctaVariant is "secondary" for both banner variants.
    const defaultCtaVariant = "secondary";
    const safeCtaVariant =
      ctaVariant && VALID_CTA_VARIANTS.has(ctaVariant)
        ? ctaVariant
        : defaultCtaVariant;

    // showDecorative defaults to true for both variants when not explicitly set.
    const shouldShowDecorative =
      showDecorative !== undefined ? Boolean(showDecorative) : true;

    // Build breadcrumb items: full array takes precedence over the label+href shortcut.
    let breadcrumbItems = [];
    if (Array.isArray(breadcrumbs) && breadcrumbs.length > 0) {
      breadcrumbItems = breadcrumbs;
    } else if (label && href) {
      breadcrumbItems = [
        { label, href },
        { label: "Current page", isCurrent: true },
      ];
    }

    const bannerClass = `banner banner--${safeVariant}`;

    // The CTA renders inline under the description only when the links panel
    // is also present. Otherwise it takes over the links column's position
    // instead -- see renderCtaAside.
    const hasLinks =
      Boolean(linksHeading) &&
      VALID_LINKS_HEADINGS.has(linksHeading) &&
      Array.isArray(links) &&
      links.length > 0;
    const ctaHtml = renderCta(ctaText, ctaHref, safeCtaVariant);
    const asideHtml = hasLinks
      ? renderLinks(linksHeading, links, isSecondary)
      : ctaText
        ? renderCtaAside(ctaHtml)
        : "";

    return /*html*/ `
<div class="fullwidth ${bannerClass}" data-variant="${safeVariant}">
  ${shouldShowDecorative ? renderDecorative() : ""}
      <div class="banner__container">
        ${renderBreadcrumbs(breadcrumbItems)}
        <div class="banner__content">
          <div class="banner__main">
            <h1 class="banner__title" data-sq-field="title">${esc(title)}</h1>
            ${renderDescription(description, descriptionLinkText, descriptionLinkHref)}
            ${hasLinks ? ctaHtml : ""}
          </div>
          ${asideHtml}
        </div>
      </div>
</div>
`;
  },
};
